// 1. 选择正确的时间语义
LocalDate billDate = LocalDate.of(2026, 6, 18);
LocalDateTime meetingLocal = LocalDateTime.of(2026, 6, 18, 10, 30);
ZoneId shanghaiZone = ZoneId.of("Asia/Shanghai");
ZonedDateTime meetingInShanghai = meetingLocal.atZone(shanghaiZone);
Instant auditTime = meetingInShanghai.toInstant();

// 2. Duration 与 Period 的差异
Duration ttl = Duration.ofMinutes(30);          // 机器时间上的持续时长
Period oneBillingCycle = Period.ofMonths(1);    // 日历意义上的一个月

// 3. 线程安全格式化
static final DateTimeFormatter LOG_TIME =
    DateTimeFormatter.ISO_OFFSET_DATE_TIME;
String text = OffsetDateTime.now().format(LOG_TIME);
OffsetDateTime parsed = OffsetDateTime.parse(text, LOG_TIME);

// 4. 与旧 Date 互转
Date legacyDate = Date.from(auditTime);
Instant back = legacyDate.toInstant();
